CREATE FUNCTION calculate_loan_status()
    RETURNS SETOF loan_last
    AS $$
    DECLARE temp_table TABLE (loan_id int, status text);
    BEGIN INSERT INTO temp_table
    SELECT loan_id, status FROM loan_first WHERE status = 'A';
    INSERT INTO loan_last SELECT loan_id, status FROM temp_table;
    RETURN;
    END;
    $$ LANGUAGE plpgsql;

