FROM (SELECT Row_ID, DENSE_RANK() OVER (PARTITION BY CustomerID ORDER BY Consumption ASC) AS NewRank
      FROM yearmonth) AS SRC
WHERE SRC.Row_ID = TGT.Row_ID;

